/// <summary>
/// AVA/WEN/2025/01/24  AVA_013036_ReverseJournal
/// </summary>
internal final class AVACreateReversalJourController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(AVACreateReversalJourService), methodStr(AVACreateReversalJourService, process), SysOperationExecutionMode::Synchronous);
}

public static AVACreateReversalJourController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACreateReversalJourController controller;
    controller = new AVACreateReversalJourController();
    controller.parmExecutionMode(_executionMode);
    controller.parmLoadFromSysLastValue(false);
    return controller;
}

public static void main(Args _args)
{
    AVACreateReversalJourController controller;
    AVACreateReversalJourContract contract;
    Set recordSet;
    MultiSelectionHelper multiselectionHelper;
    LedgerJournalTable  ledgerJournalTable;
    controller = AVACreateReversalJourController::construct();
    controller.parmArgs(_args);
    contract = controller.getDataContractObject();
    if (_args.record() && _args.dataset() == tableNum(ledgerJournalTable))
    {
        if (_args && _args.caller() is FormRun)
        {
            recordSet = new Set(Types::Record);
            multiselectionHelper = MultiSelectionHelper::createFromCaller(_args.caller());

            ledgerJournalTable = multiselectionHelper.getFirst();
            while (ledgerJournalTable)
            {
                recordSet.add(ledgerJournalTable);

                ledgerJournalTable = multiselectionHelper.getNext();
            }
        }

        contract = controller.getDataContractObject();
        contract.parmRecordCon(recordSet.pack());
    }
    else 
    {
        throw Error(Error::missingRecord(tableStr(ledgerJournalTable)));
    }

    controller.startOperation();
}

protected boolean validate()
{
    AVACreateReversalJourContract    contract;
    boolean                         isValid = true;
    contract = this.getDataContractObject();

    if (!contract.parmUseExistingDates() && !contract.parmReversalDate())
    {
        isValid = checkFailed("@NDX:NXAReversalDateIsRequired");
    }

    return isValid;
}
